func TestReproLeak(t *testing.T) {
	baseline := liveGoroutines()
	r := &Retrier{maxAttempts: 100, backoff: time.Hour, send: func([]byte) error { return errors.New("fail") }}
	r.RetryAsync([]byte("ping"))
	time.Sleep(50 * time.Millisecond)
	if liveGoroutines() <= baseline { t.Fatal("retry goroutine leaked") }
}
